        ["`contraindicated_for[]`", "object[]", "`kind` = `emotion` (id is an emotion id; the activity is excluded for that emotion), `condition` (user attribute, e.g. `heart_condition`, `rumination_prone`, `social_anxiety`) or `context` (e.g. `near_bedtime`, `quick_mood_lift_needed`, `high_intensity`); with `reason`"],
        ["`rule_classes`", "string[]", "matching-rule classes this activity belongs to (BREATHE, MOVE-LOW, …)"],
        ["`evidence_summary`", "object", "link counts, emotions with benefit / null-or-harm evidence, best verification status"],
        ["`source_activity_labels`, `source_notes_files`", "string[]", "provenance"],
